from ortools.linear_solver import pywraplp
import json

def solve_inspection_route():
    solver = pywraplp.Solver.CreateSolver("SCIP")
    if not solver:
        print("Solver creation failed")
        return

    intersections = [0, 1, 2, 3, 4, 5, 6]

    directed_arcs = [
        (0, 1), (1, 2), (2, 3), (3, 2), (3, 4), (4, 5), 
        (5, 4), (5, 6), (6, 0), (0, 6), (1, 5)
    ]

    one_way_arcs = [(0, 1), (1, 2), (3, 4), (5, 6), (1, 5)]

    two_way_pairs = [
        ((2, 3), (3, 2)),
        ((4, 5), (5, 4)),
        ((6, 0), (0, 6))
    ]

    travel_time = {
        (0, 1): 3, (1, 2): 2, (2, 3): 4, (3, 2): 4,
        (3, 4): 1, (4, 5): 2, (5, 4): 2, (5, 6): 3,
        (6, 0): 5, (0, 6): 5, (1, 5): 3
    }

    inspect_time = {
        (0, 1): 5,
        (1, 2): 3,
        (2, 3): 7,
        (3, 4): 2,
        (4, 5): 4,
        (5, 6): 6,
        (6, 0): 8,
        (1, 5): 5
    }

    street_to_arcs = {
        (0, 1): [(0, 1)],
        (1, 2): [(1, 2)],
        (2, 3): [(2, 3), (3, 2)],
        (3, 4): [(3, 4)],
        (4, 5): [(4, 5), (5, 4)],
        (5, 6): [(5, 6)],
        (6, 0): [(6, 0), (0, 6)],
        (1, 5): [(1, 5)]
    }

    x = {}
    y = {}

    for (i, j) in directed_arcs:
        x[i, j] = solver.IntVar(0, solver.infinity(), f"x_{i}_{j}")
        y[i, j] = solver.BoolVar(f"y_{i}_{j}")

    for k in intersections:
        inflow = solver.Sum(x[i, k] for (i, j) in directed_arcs if j == k)
        outflow = solver.Sum(x[k, j] for (i, j) in directed_arcs if i == k)
        solver.Add(inflow == outflow, f"flow_conservation_{k}")

    outflow_from_0 = solver.Sum(x[0, j] for (i, j) in directed_arcs if i == 0)
    inflow_to_0 = solver.Sum(x[i, 0] for (i, j) in directed_arcs if j == 0)
    solver.Add(outflow_from_0 >= 1, "start_at_0")
    solver.Add(inflow_to_0 >= 1, "end_at_0")

    for (i, j) in one_way_arcs:
        solver.Add(y[i, j] == 1, f"one_way_inspection_{i}_{j}")

    for (arc1, arc2) in two_way_pairs:
        solver.Add(y[arc1] + y[arc2] == 1, f"two_way_choice_{arc1}_{arc2}")

    for (i, j) in directed_arcs:
        solver.Add(y[i, j] <= x[i, j], f"inspection_requires_traversal_{i}_{j}")

    total_inspected = solver.Sum(y[i, j] for (i, j) in directed_arcs)
    solver.Add(total_inspected == 8, "total_streets_inspected")

    total_nodes = len(intersections) - 1
    f = {}
    for (i, j) in directed_arcs:
        f[i, j] = solver.IntVar(0, total_nodes, f"f_{i}_{j}")

    outflow_depot = solver.Sum(f[0, j] for (i, j) in directed_arcs if i == 0)
    inflow_depot = solver.Sum(f[i, 0] for (i, j) in directed_arcs if j == 0)
    solver.Add(outflow_depot - inflow_depot == total_nodes, "depot_flow_balance")

    for k in intersections:
        if k != 0:
            inflow_k = solver.Sum(f[i, k] for (i, j) in directed_arcs if j == k)
            outflow_k = solver.Sum(f[k, j] for (i, j) in directed_arcs if i == k)
            solver.Add(inflow_k - outflow_k == 1, f"node_flow_balance_{k}")

    M = total_nodes
    for (i, j) in directed_arcs:
        solver.Add(f[i, j] <= M * x[i, j], f"flow_on_traversed_arc_{i}_{j}")

    travel_cost = solver.Sum(travel_time[i, j] * x[i, j] for (i, j) in directed_arcs)

    inspection_cost = 0
    for street, arcs in street_to_arcs.items():
        street_inspection = solver.Sum(y[arc] for arc in arcs)
        inspection_cost += inspect_time[street] * street_inspection

    total_cost = travel_cost + inspection_cost
    solver.Minimize(total_cost)

    status = solver.Solve()

    if status == pywraplp.Solver.OPTIMAL:
        total_cost_value = solver.Objective().Value()

        x_vals = {(i, j): x[i, j].solution_value() for (i, j) in directed_arcs}

        adj = {i: [] for i in intersections}
        for (i, j) in directed_arcs:
            count = int(x_vals[i, j] + 0.5)
            for _ in range(count):
                adj[i].append(j)

        route = []
        stack = [0]

        while stack:
            current = stack[-1]
            if adj[current]:
                next_node = adj[current].pop()
                stack.append(next_node)
            else:
                route.append(stack.pop())

        route.reverse()

        print(json.dumps({
            "route": route,
            "total_cost": int(total_cost_value)
        }))

    else:
        print(f"No optimal solution found. Status: {status}")

if __name__ == "__main__":
    solve_inspection_route()
